(function(){
  'use strict';
  const C=window.AtelierCore, $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const NAV=[['pilotage','◫','Pilotage'],['postes','▦','Postes de travail'],['taches','☷','Tâches'],['dossier','▣','Dossier commun'],['transmissions','⇄','Transmissions IA'],['decisions','◇','Décisions'],['github','⌘','GitHub'],['prompts','✎','Prompts'],['comparateur','◧','Comparateur'],['sauvegardes','↧','Sauvegardes']];
  const SNAP_KEY='atelier-ia-snapshots-v2', BEFORE_KEY='atelier-ia-before-v2';
  let state, lastRaw=null, storageError='', writeLock='', projectId='', page='pilotage', roleId='', docTab='documents', filterRole='',filterOwner='',filterQuery='', sessionToken='',sessionUser='',dbPromise,toastTimer,folderHandle=null,folderAuto=false,folderTimer,folderWriting=false,folderAgain=false;
  let compareDraft={title:'',a:'',b:'',notes:'',verdict:'',scoreA:'',scoreB:''};
  let transferDraft={from:'Moi',to:'ChatGPT',level:'standard',role:'pilotage',task:'',request:''};
  const githubCache=new Map(),prepared=new Map(),remoteDossiers=new Map();
  let draftProjectId='';
  const gh=new window.AtelierGitHub(()=>sessionToken);
  function now(){return new Date().toISOString();}
  function formatDate(v){if(!v)return 'Pas encore renseigné';const d=new Date(v);return isNaN(d)?v:d.toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'});}
  function fmtSize(n){return n<1024?n+' o':n<1024*1024?(n/1024).toFixed(0)+' Ko':(n/1048576).toFixed(1)+' Mo';}
  function current(){return state.projects.find(p=>p.id===projectId)||state.projects[0];}
  function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
  function announce(){const n=$('#notice');if(writeLock==='corrupt'){n.innerHTML='Les données enregistrées sont illisibles et ont été conservées. Exporte leur copie ou restaure une sauvegarde depuis l’espace Sauvegardes. <button class="button small" data-action="export-raw">Récupérer les données originales</button>';n.hidden=false;}else if(writeLock==='conflict'){n.innerHTML='Le projet a été modifié dans une autre fenêtre. Exporte ton travail de cette fenêtre, puis recharge pour reprendre la version enregistrée. <button class="button small" data-action="reload">Recharger</button>';n.hidden=false;}else if(storageError){n.textContent=storageError+' Exporte une sauvegarde pour conserver ton travail.';n.hidden=false;}else{n.hidden=true;n.textContent='';}}
  function load(){
    try{lastRaw=localStorage.getItem(C.KEY);state=lastRaw?C.normalizeState(JSON.parse(lastRaw)):C.starter();}
    catch(e){state=C.starter();if(lastRaw)writeLock='corrupt';else storageError='Le stockage du navigateur est indisponible : les modifications restent dans cette fenêtre.';}
    if(lastRaw&&!writeLock){try{if(JSON.parse(lastRaw).schemaVersion!==2&&!localStorage.getItem(BEFORE_KEY))localStorage.setItem(BEFORE_KEY,lastRaw);}catch{storageError='La copie avant migration n’a pas pu être enregistrée. Exporte tes données avant de poursuivre.';}}
    try{projectId=localStorage.getItem('atelier-ia-project')||state.projects[0]?.id||'';}catch{};
    if(!state.projects.some(p=>p.id===projectId))projectId=state.projects[0]?.id||'';
  }
  function snapshots(){try{const x=JSON.parse(localStorage.getItem(SNAP_KEY)||'[]');return Array.isArray(x)?x:[];}catch{return [];}}
  function snapshot(force=false){if(writeLock)return;try{const list=snapshots();if(force||!list.length||Date.now()-Date.parse(list[0].date)>300000){list.unshift({id:C.uid(),date:now(),data:C.clone(state)});localStorage.setItem(SNAP_KEY,JSON.stringify(list.slice(0,5)));}}catch{}}
  function persist(){
    if(writeLock){announce();return false;}
    state.updatedAt=now();
    try{const stored=localStorage.getItem(C.KEY);if(stored!==lastRaw){writeLock='conflict';announce();return false;}const serialized=JSON.stringify(state);localStorage.setItem(C.KEY,serialized);lastRaw=serialized;storageError='';$('#saveStatus').textContent='Enregistré · '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});}
    catch(e){storageError='L’enregistrement local a échoué (stockage saturé ou bloqué).';$('#saveStatus').textContent='À sauvegarder';announce();return false;}
    announce();if(folderAuto&&folderHandle){clearTimeout(folderTimer);folderTimer=setTimeout(()=>writeFolder().catch(e=>{folderAuto=false;toast(e.message);}),1600);}return true;
  }
  function editable(){if(writeLock){toast(writeLock==='corrupt'?'Restaure ou importe une sauvegarde avant de modifier les données.':'Recharge la version enregistrée, après avoir exporté ton travail.');return false;}return true;}
  function change(fn,redraw=true){if(!editable())return false;snapshot();fn();persist();if(redraw)render();return true;}
  function navigate(target){if(location.hash==='#'+target){route();return;}location.hash=target;}
  function setProject(id){projectId=id;filterRole='';filterOwner='';filterQuery='';transferDraft.task='';try{localStorage.setItem('atelier-ia-project',id);}catch{}render();}
  function route(){const parts=location.hash.replace(/^#/,'').split('/');page=NAV.some(n=>n[0]===parts[0])?parts[0]:'pilotage';roleId=page==='postes'&&C.ROLES.some(r=>r.id===parts[1])?parts[1]:'';render();}
  function btn(action,label,style='',extra=''){return `<button class="button ${style}" data-action="${action}" ${extra}>${label}</button>`;}
  function link(href,label,style=''){return `<a class="button ${style}" href="${esc(href)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;}
  function externalHref(href){try{const u=new URL(href);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
  function empty(message,action=''){return `<div class="empty">${message}${action?'<div class="toolbar" style="justify-content:center;margin-top:12px">'+action+'</div>':''}</div>`;}
  function heading(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${desc?'<p>'+desc+'</p>':''}</div>${actions?'<div class="toolbar">'+actions+'</div>':''}</div>`;}
  function roleOptions(selected,all=false){return (all?'<option value="">Tous les postes</option>':'')+C.ROLES.map(r=>`<option value="${r.id}" ${selected===r.id?'selected':''}>${r.n} · ${esc(r.name)}</option>`).join('');}
  function statusOptions(selected){return C.STATUSES.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${s.name}</option>`).join('');}
  function fieldsTask(p,t){const deps=C.unresolved(p,t);return [t.blocked,...deps.map(x=>'Dépend de : '+x.title)].filter(Boolean).join(' · ');}
  function taskCard(p,t){const blocker=fieldsTask(p,t);return `<article class="task-card ${blocker?'blocked':''}"><span class="badge ${t.priority==='high'?'amber':''}">${esc(C.role(t.role).name)}</span><h3>${esc(t.title)}</h3>${t.deliverable?'<p>'+esc(t.deliverable)+'</p>':''}${blocker?'<div class="block-note">'+esc(blocker)+'</div>':''}<div class="task-foot"><small>${esc(t.owner)}</small>${btn('edit-task','Ouvrir','small',`data-id="${esc(t.id)}"`)}</div></article>`;}
  function render(){
    const p=current();if(p)projectId=p.id;
    if(projectId!==draftProjectId)loadProjectDraft();
    $('#nav').innerHTML=NAV.map(([id,icon,name],i)=>(i===7?'<div class="nav-separator">OUTILS COMMUNS</div>':'')+`<a href="#${id}" ${page===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${name}</a>`).join('');
    $('#projectSelect').innerHTML=state.projects.length?state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===projectId?'selected':''}>${esc(p.name)}</option>`).join(''):'<option value="">Aucun projet</option>';
    $('#projectName').textContent=p?.name||'Mon Atelier IA';$('#sectionName').textContent=NAV.find(n=>n[0]===page)[2];
    $('#saveStatus').textContent=storageError?'À sauvegarder':writeLock?'Données protégées':state.updatedAt?'Enregistré · '+formatDate(state.updatedAt).split(' ').slice(-1).join(' '):'Enregistrement automatique';
    announce();const m=$('#main');
    if(!p&&!['sauvegardes','prompts','comparateur'].includes(page)){m.innerHTML=`<div class="card project-empty"><div class="eyebrow">BIENVENUE</div><h1>Un premier projet.</h1><p class="muted">Donne-lui un nom pour ouvrir son dossier commun et ses dix postes de travail.</p>${btn('new-project','Créer un projet','primary')}</div>`;return;}
    const views={pilotage:dashboard,postes:rolesPage,taches:tasksPage,dossier:dossierPage,transmissions:transferPage,decisions:decisionsPage,github:githubPage,prompts:promptsPage,comparateur:comparePage,sauvegardes:backupPage};
    m.innerHTML=views[page](p);
  }
  function dashboard(p){
    const open=p.workItems.filter(t=>t.status!=='done'),review=p.workItems.filter(t=>t.status==='review'),blocked=open.filter(t=>fieldsTask(p,t)),done=p.workItems.length-open.length;
    const sorted=[...open].sort((a,b)=>({high:0,normal:1,low:2}[a.priority]-{high:0,normal:1,low:2}[b.priority]));
    const completedDocs=p.documents.filter(d=>d.content.trim()).length+(p.context.trim()?1:0)+(p.decisions.trim()?1:0),totalDocs=p.documents.length+2;
    const recent=p.decisionLog.filter(d=>d.status==='validated').slice(0,3);
    return heading('TABLEAU DE PILOTAGE',esc(p.name),esc(p.description)||'Définis le cap, puis avance poste par poste.',btn('edit-project','Modifier le projet')+btn('new-task','＋ Nouvelle tâche','primary'))+
      `<div class="grid four"><div class="card stat"><div class="label">TRAVAIL À FAIRE</div><strong>${open.length.toString().padStart(2,'0')}</strong><small>tâche${open.length>1?'s':''} en cours de parcours</small></div><div class="card stat"><div class="label">À VÉRIFIER</div><strong>${review.length.toString().padStart(2,'0')}</strong><small>résultat${review.length>1?'s':''} à contrôler</small></div><div class="card stat warn"><div class="label">BLOCAGES</div><strong>${blocked.length.toString().padStart(2,'0')}</strong><small>tâche${blocked.length>1?'s':''} avec un obstacle</small></div><div class="card stat good"><div class="label">TERMINÉ</div><strong>${done.toString().padStart(2,'0')}</strong><small>sur ${p.workItems.length} tâche${p.workItems.length>1?'s':''}</small></div></div>
      <div class="overview-columns"><section class="card"><div class="card-heading"><h2>Les prochaines actions</h2><a class="text-button" href="#taches">Voir les tâches →</a></div>${sorted.length?sorted.slice(0,4).map(t=>`<div class="next-task"><span class="task-dot" aria-hidden="true"></span><div class="task-info"><strong>${esc(t.title)}</strong><small>${esc(C.role(t.role).name)} · ${esc(t.owner)}${fieldsTask(p,t)?' · '+esc(fieldsTask(p,t)):''}</small></div>${btn('edit-task','Ouvrir','small',`data-id="${esc(t.id)}"`)}</div>`).join(''):empty('Le tableau est prêt pour ta prochaine idée.',btn('new-task','Ajouter une tâche','small'))}</section>
      <section class="card tint"><div class="card-heading"><h2>Le dossier commun</h2><span class="badge green">${completedDocs}/${totalDocs} repères</span></div><p class="muted">Le cap, les règles et les fichiers qui accompagnent tous les postes.</p><div class="progress"><span style="width:${Math.round(completedDocs/Math.max(1,totalDocs)*100)}%"></span></div><div class="summary-line">${p.assets.length} fichier${p.assets.length>1?'s':''} · ${p.decisionLog.filter(d=>d.status==='validated').length} décision${p.decisionLog.filter(d=>d.status==='validated').length>1?'s':''} validée${p.decisionLog.filter(d=>d.status==='validated').length>1?'s':''}</div><div class="mini-links"><a href="#dossier">Ouvrir le dossier →</a><a href="#transmissions">Préparer une transmission →</a></div></section></div>
      <div class="grid two section-gap"><section class="card"><div class="card-heading"><h2>Décisions à garder en vue</h2><a href="#decisions" class="text-button">Le journal →</a></div>${recent.length?recent.map(d=>`<div class="decision-row"><span class="decision-indicator validated"></span><div class="content"><p>${esc(d.text)}</p><small class="muted">${esc(formatDate(d.date))}</small></div></div>`).join(''):p.decisions?'<p class="document-text">'+esc(p.decisions)+'</p>':empty('Les décisions validées apparaîtront ici.')}</section><section class="card"><div class="card-heading"><h2>Version & dépôt</h2><span class="badge">${esc(p.activeVersion||'À renseigner')}</span></div><p>${p.github.repo?'<strong>'+esc(p.github.owner+'/'+p.github.repo)+'</strong><br><span class="muted">Dépôt associé au projet.</span>':'<span class="muted">Associe le dépôt qui contient le code ou les documents du projet.</span>'}</p><div class="toolbar"><a class="button" href="#github">Ouvrir GitHub</a>${btn('edit-project','Renseigner la version','ghost')}</div></section></div>
      <div class="card-heading section-title"><h2>Les postes de travail</h2><a href="#postes" class="text-button">Toute l’équipe →</a></div><div class="grid three">${C.ROLES.map(r=>`<a href="#postes/${r.id}" class="card" style="text-decoration:none"><div class="eyebrow">POSTE ${r.n}</div><h3>${esc(r.name)}</h3><span class="muted" style="font-size:11px">IA : ${esc(r.primaryAI)} · ${p.workItems.filter(t=>t.role===r.id&&t.status!=='done').length} tâche(s) à suivre →</span></a>`).join('')}</div>`;
  }
  function aiAdvice(r){return '<p class="help"><strong>IA principale : '+esc(r.primaryAI)+'</strong> · Contrôle : '+esc(r.reviewAI)+' (conseil, choix modifiable)</p>';}
  function selectRoleAI(id,review=false){transferDraft.to=review?C.role(id).reviewAI:C.role(id).primaryAI;}
  function transferRoleAction(role,review=false){transferDraft.role=role;transferDraft.task='';transferDraft.request='';selectRoleAI(role,review);change(()=>current().transferDraft={...transferDraft},false);navigate('transmissions');}
  function performance(p,roleId){
    const entries=p.handoffs.filter(h=>h.role===roleId&&['ChatGPT','Claude'].includes(h.to));
    return ['ChatGPT','Claude'].map(ai=>{
      const own=entries.filter(h=>h.to===ai),rated=own.filter(h=>h.rating>0);
      return {ai,total:own.length,rated:rated.length,average:rated.length?(rated.reduce((s,h)=>s+h.rating,0)/rated.length).toFixed(1):'',completed:own.filter(h=>h.outcome==='done').length};
    });
  }
  function performanceHtml(p,id){
    const stats=performance(p,id);
    return '<div class="grid two">'+stats.map(s=>'<div class="card"><strong>'+esc(s.ai)+'</strong><p>'+s.total+' mission(s) archivée(s) · '+s.completed+' déclarée(s) réussie(s)</p><p class="muted">'+(s.rated?s.average+'/5 sur '+s.rated+' avis personnel(s)':'Aucune évaluation pour le moment')+'</p></div>').join('')+'</div><p class="help">Appréciations personnelles, non mesures objectives. Un faible nombre de missions ne permet pas de désigner une IA gagnante.</p>';
  }
  function missionHistory(p,id){
    const missions=p.handoffs.filter(h=>h.role===id);
    return '<h2 class="section-title">Historique des missions · '+missions.length+'</h2>'+(missions.length?'<section class="card">'+missions.map(h=>'<div class="archive-row"><div class="content"><strong>'+esc(h.title)+'</strong><small>'+esc(h.to)+' · '+esc(formatDate(h.date))+' · '+esc(({pending:'En attente de résultat',done:'Réussi',partial:'Partiel',failed:'Non satisfaisant'})[h.outcome]||'En attente')+(h.rating?' · '+h.rating+'/5':'')+'</small>'+(h.result?'<p class="muted">'+esc(h.result)+'</p>':'')+'</div><div class="toolbar">'+btn('edit-mission','Résultat / évaluation','small',`data-id="${esc(h.id)}"`)+btn('open-transfer','Consigne','small ghost',`data-id="${esc(h.id)}"`)+'</div></div>').join('')+'</section>':empty('Aucune mission archivée pour ce poste. Une transmission archivée apparaîtra ici.'));
  }
  function editMission(p,h){
    if(!h)return;
    editor('Résultat de mission · '+h.title,`<p class="muted">IA : ${esc(h.to)} · Poste : ${esc(h.role?C.role(h.role).name:'Non renseigné')}</p>
      <label for="missionOutcome">Résultat</label><select id="missionOutcome" name="outcome">
      ${[['pending','En attente'],['done','Réussi'],['partial','Partiel'],['failed','Non satisfaisant']].map(([id,name])=>`<option value="${id}" ${h.outcome===id?'selected':''}>${name}</option>`).join('')}</select>
      <label for="missionResult">Livrable ou résultat obtenu</label><textarea id="missionResult" name="result" placeholder="Ce que l’IA a réellement produit, éventuellement avec un lien vers le fichier ou le commit.">${esc(h.result)}</textarea>
      <label for="missionRating">Appréciation personnelle</label><select id="missionRating" name="rating">${[['0','Pas encore noté'],['1','1 / 5'],['2','2 / 5'],['3','3 / 5'],['4','4 / 5'],['5','5 / 5']].map(([v,n])=>`<option value="${v}" ${Number(h.rating)===Number(v)?'selected':''}>${n}</option>`).join('')}</select>
      <label for="missionNotes">Qualité, limites, corrections nécessaires</label><textarea id="missionNotes" name="notes">${esc(h.notes)}</textarea>`,fd=>change(()=>{
      h.outcome=fd.get('outcome');h.result=fd.get('result').trim();h.rating=Number(fd.get('rating'));h.notes=fd.get('notes').trim();h.evaluatedAt=now();
    }));
  }
  function rolesPage(p){
    if(roleId){const r=C.role(roleId),items=p.workItems.filter(t=>t.role===r.id);return heading('POSTE '+r.n,esc(r.name),esc(r.mission),'<a class="button" href="#postes">Tous les postes</a>'+btn('new-task','＋ Confier une tâche','primary',`data-role="${r.id}"`))+
      `<div class="card role-detail"><div class="eyebrow">CE QUE CE POSTE TRANSMET</div><h2>${esc(r.output)}</h2>${aiAdvice(r)}<p class="muted">Il s’appuie sur le dossier commun et indique les vérifications réalisées ainsi que les points à reprendre.</p><div class="toolbar">${btn('role-handoff','Mission pour '+r.primaryAI,'primary',`data-role="${r.id}"`)}${btn('role-review','Contrôle par '+r.reviewAI,'',`data-role="${r.id}"`)}<a class="button" href="#dossier">Consulter le dossier commun</a></div></div><h2 class="section-title">Travail confié à ce poste</h2><div class="grid three">${items.length?items.map(t=>taskCard(p,t)).join(''):empty('Aucune tâche confiée pour le moment.')}</div><h2 class="section-title">Bilan ChatGPT / Claude</h2>${performanceHtml(p,r.id)}${missionHistory(p,r.id)}`;}
    return heading('ÉQUIPE DU PROJET','Dix postes, un dossier commun.','Chaque poste a sa mission et un résultat à transmettre. Toi, ChatGPT ou Claude pouvez intervenir selon la tâche.')+
      `<div class="grid three">${C.ROLES.map(r=>{const open=p.workItems.filter(t=>t.role===r.id&&t.status!=='done').length;return `<article class="card role-card"><div class="role-number"><span>POSTE ${r.n}</span><span class="badge">${open} à suivre</span></div><div class="role-short">${esc(r.short)}</div><h3>${esc(r.name)}</h3><p class="muted">${esc(r.mission)}</p>${aiAdvice(r)}<small class="muted">${p.handoffs.filter(h=>h.role===r.id).length} mission(s) suivie(s)</small><div class="toolbar"><a class="button small" href="#postes/${r.id}">Ouvrir le poste →</a>${btn('new-task','＋ Tâche','small ghost',`data-role="${r.id}"`)}</div></article>`;}).join('')}</div>`;
  }
  function tasksPage(p){
    const items=p.workItems.filter(t=>(!filterRole||t.role===filterRole)&&(!filterOwner||t.owner===filterOwner)&&(!filterQuery||(t.title+' '+t.objective+' '+t.deliverable).toLocaleLowerCase('fr').includes(filterQuery.toLocaleLowerCase('fr'))));
    const owners=[...new Set(p.workItems.map(t=>t.owner))];
    return heading('TABLEAU DES TÂCHES','Du besoin au résultat vérifié.','Ouvre une tâche pour retrouver son objectif, ses fichiers, le résultat attendu et les vérifications.',btn('new-task','＋ Nouvelle tâche','primary'))+
      `<div class="filters"><div><label for="taskSearch">Rechercher</label><input id="taskSearch" placeholder="Une tâche, un résultat…" value="${esc(filterQuery)}"></div><div><label for="filterRole">Poste</label><select id="filterRole">${roleOptions(filterRole,true)}</select></div><div><label for="filterOwner">Intervenant</label><select id="filterOwner"><option value="">Tous les intervenants</option>${owners.map(o=>`<option ${o===filterOwner?'selected':''}>${esc(o)}</option>`).join('')}</select></div></div><div class="board">${C.STATUSES.map(s=>`<section class="board-column" aria-label="${s.name}"><div class="board-title"><span>${s.name}</span><span>${items.filter(t=>t.status===s.id).length}</span></div>${items.filter(t=>t.status===s.id).map(t=>taskCard(p,t)).join('')||'<div class="empty">Aucune tâche</div>'}</section>`).join('')}</div>`;
  }
  function dossierPage(p){
    const tabs=[['documents','Cap & documents'],['assets','Fichiers & médias'],['folder','Dossier sur l’ordinateur']];
    let body='';
    if(docTab==='documents')body=`<div class="card"><div class="card-heading"><h2>Les repères permanents</h2><span class="badge green">Enregistrement automatique</span></div><label for="projectContext">Objectif et contexte</label><textarea id="projectContext" data-project-field="context" placeholder="À qui sert ce projet ? Que doit-il permettre ?">${esc(p.context)}</textarea><label for="projectRules">Règles et décisions conservées</label><textarea id="projectRules" data-project-field="decisions" placeholder="Les choix déjà arrêtés, les contraintes à respecter…">${esc(p.decisions)}</textarea>${p.tasks?`<details class="disclosure"><summary>Notes de tâches conservées depuis la V1</summary><p class="document-text">${esc(p.tasks)}</p></details>`:''}</div><div class="card-heading section-title"><h2>Documents de référence</h2>${btn('new-document','＋ Ajouter un document','small')}</div><div class="grid two">${p.documents.map(d=>`<article class="card document-card"><h3>${esc(d.title)}</h3><small>${d.updatedAt?'Mis à jour le '+esc(formatDate(d.updatedAt)):'Document à compléter'}</small><div class="document-text">${esc(d.content)||'Les éléments de référence de ce document seront partagés avec les postes.'}</div><div class="toolbar">${btn('edit-document','Modifier','small',`data-id="${esc(d.id)}"`)}${btn('copy-document','Copier','small ghost',`data-id="${esc(d.id)}"`)}</div></article>`).join('')}</div>`;
    if(docTab==='assets')body=`<div class="doc-top"><p class="muted" style="font-size:12px">Les originaux sont conservés sans réduire leur définition.</p>${btn('add-assets','＋ Ajouter des fichiers','primary')}</div><div class="card">${p.assets.length?p.assets.map(a=>`<div class="asset-row"><div class="file-icon">${esc((a.name.split('.').pop()||'DOC').toUpperCase().slice(0,4))}</div><div class="content"><strong>${esc(a.name)}</strong><small>${esc(fmtSize(a.size))} · ${esc(C.role(a.role).name)} · ${esc(formatDate(a.date))}</small>${a.note?'<small>'+esc(a.note)+'</small>':''}</div><span class="badge ${['validated','integrated','tested'].includes(a.status)?'green':'amber'}">${C.ASSET_STATUSES.find(s=>s.id===a.status)?.name}</span><div class="toolbar">${btn('download-asset','Ouvrir / télécharger','small',`data-id="${esc(a.id)}"`)}${btn('edit-asset','Suivi','small',`data-id="${esc(a.id)}"`)}</div></div>`).join(''):empty('Ajoute les photos, illustrations, patrons, documents ou sons utiles au projet.',btn('add-assets','Choisir des fichiers','small'))}</div>`;
    if(docTab==='folder')body=`<div class="grid two"><section class="card"><div class="eyebrow">LE DOSSIER DU PROJET</div><h2>Un dossier utilisable partout.</h2><p class="muted">Exporte le dossier commun, les tâches et les fichiers originaux dans une archive ZIP. Le fichier projet.json permet de réimporter le projet.</p>${btn('export-project','Exporter le dossier complet (.zip)','primary')}<p class="help" style="margin:15px 0 0">Le ZIP contient DOSSIER_COMMUN.md, projet.json et un sous-dossier de pièces jointes.</p></section><section class="card"><div class="eyebrow">SUR CET ORDINATEUR</div><h2>Associer un dossier local</h2><p class="muted">L’atelier y crée son propre sous-dossier et y écrit le projet et ses originaux. Réassocie ce dossier après avoir fermé le navigateur.</p><div class="toolbar">${btn('choose-folder','Choisir un dossier','primary')}${folderHandle?btn('write-folder','Enregistrer maintenant'):''}</div><div class="connection-status ${folderHandle?'':'disconnected'}">${folderHandle?'Dossier sélectionné : '+esc(folderHandle.name):'Aucun dossier sélectionné pour cette session.'}</div>${folderHandle?`<label class="check-label" style="margin-top:16px"><input id="folderAuto" type="checkbox" ${folderAuto?'checked':''}>Enregistrer automatiquement le projet actif dans ce dossier</label>`:''}<p class="help" style="margin-top:15px">Cette option dépend du navigateur. Si elle est indisponible, utilise l’export ZIP.</p></section></div>`;
    return heading('RÉFÉRENCE DU PROJET','Le dossier commun.','Les mêmes objectifs, décisions et fichiers accompagnent chaque poste et chaque transmission.',btn('copy-dossier','Copier le dossier')+btn('export-project','Exporter le dossier','primary'))+
      `<div class="tabs">${tabs.map(([id,title])=>`<button class="button" aria-pressed="${id===docTab}" data-action="dossier-tab" data-id="${id}">${title}</button>`).join('')}</div>`+body;
  }
  function transferPage(p){
    const output=C.context(p,transferDraft.level,transferDraft.role,transferDraft.task,transferDraft.request);
    return heading('TRANSMISSION ENTRE IA','Passer le relais, sans perdre le fil.','Prépare une consigne pour le poste choisi, puis copie-la dans ChatGPT ou Claude. Le transfert reste manuel.')+
      `<div class="grid two"><section class="card"><h2>Préparer la mission</h2><div class="field-row"><div><label for="transferFrom">Depuis</label><select id="transferFrom" data-transfer-field="from">${['Moi','ChatGPT','Claude'].map(x=>`<option ${transferDraft.from===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="transferTo">Vers</label><select id="transferTo" data-transfer-field="to">${['ChatGPT','Claude','Moi'].map(x=>`<option ${transferDraft.to===x?'selected':''}>${x}</option>`).join('')}</select></div></div><label for="transferRole">Poste de travail</label><select id="transferRole" data-transfer-field="role">${roleOptions(transferDraft.role)}</select><p id="aiRecommendation" class="help">Conseil pour ce poste : ${esc(C.role(transferDraft.role).primaryAI)} en principal · ${esc(C.role(transferDraft.role).reviewAI)} en contrôle. Le choix « Vers » reste libre.</p><label for="transferTask">Tâche à transmettre</label><select id="transferTask" data-transfer-field="task"><option value="">Mission libre</option>${p.workItems.map(t=>`<option value="${esc(t.id)}" ${transferDraft.task===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select><label for="transferLevel">Quantité de contexte</label><select id="transferLevel" data-transfer-field="level"><option value="court" ${transferDraft.level==='court'?'selected':''}>Court · l’essentiel du projet</option><option value="standard" ${transferDraft.level==='standard'?'selected':''}>Standard · décisions et documents</option><option value="complet" ${transferDraft.level==='complet'?'selected':''}>Complet · suivi et catalogue des fichiers</option></select><label for="transferRequest">Demande actuelle</label><textarea id="transferRequest" data-transfer-field="request" placeholder="Ce que tu demandes à cette IA pour cette tâche…">${esc(transferDraft.request)}</textarea><p class="help">Les pièces jointes sont à ajouter dans la conversation si la mission en a besoin.</p></section><section class="card"><div class="card-heading"><h2>Le dossier de transmission</h2><span id="transferLength" class="badge">${output.length.toLocaleString('fr-FR')} caractères</span></div><label for="transferOutput" class="muted">Texte prêt à copier</label><textarea id="transferOutput" class="transfer-output" readonly>${esc(output)}</textarea><div class="toolbar">${btn('copy-transfer','Copier la transmission','primary')}${btn('archive-transfer','Archiver')}<a id="openAI" class="button" href="${transferDraft.to==='Claude'?'https://claude.ai':'https://chatgpt.com'}" target="_blank" rel="noopener noreferrer">Ouvrir ${transferDraft.to==='Moi'?'ChatGPT':esc(transferDraft.to)} ↗</a></div><div class="transfer-steps"><span>1. Copier la mission</span><span>2. La coller dans l’IA</span><span>3. Reporter le résultat dans la tâche</span></div></section></div><h2 class="section-title">Transmissions archivées</h2><section class="card">${p.handoffs.length?p.handoffs.map(h=>`<div class="archive-row"><div class="content"><strong>${esc(h.title)}</strong><small>${esc(h.from)} → ${esc(h.to)} · ${esc(formatDate(h.date))} · ${esc(h.role?C.role(h.role).name:'Poste non renseigné')} · ${esc(({pending:'En attente',done:'Réussi',partial:'Partiel',failed:'Non satisfaisant'})[h.outcome]||'En attente')}</small></div>${btn('open-transfer','Relire / copier','small',`data-id="${esc(h.id)}"`)}${btn('edit-mission','Noter le résultat','small ghost',`data-id="${esc(h.id)}"`)}</div>`).join(''):empty('Archive les transmissions utiles pour retrouver ce qui a été confié à chaque poste.')}</section>`;
  }
  function decisionsPage(p){return heading('JOURNAL DES DÉCISIONS','Ce qui a été décidé, et pourquoi.','Les propositions restent distinctes des décisions validées. Ces dernières alimentent le contexte partagé.',btn('new-decision','＋ Ajouter une décision','primary'))+
    (p.decisions?`<section class="card"><div class="card-heading"><h2>Règles déjà conservées</h2><a class="text-button" href="#dossier">Modifier dans le dossier →</a></div><p class="document-text">${esc(p.decisions)}</p></section>`:'')+
    `<section class="card section-gap">${p.decisionLog.length?p.decisionLog.map(d=>`<div class="decision-row"><span class="decision-indicator ${d.status}" aria-hidden="true"></span><div class="content"><p>${esc(d.text)}</p>${d.reason?'<small class="muted">'+esc(d.reason)+'</small>':''}<small class="muted" style="display:block;margin-top:7px">${esc(formatDate(d.date))}</small></div><span class="badge ${d.status==='validated'?'green':d.status==='proposed'?'amber':''}">${{validated:'Validée',proposed:'Proposée',retired:'Remplacée / retirée'}[d.status]}</span><div class="toolbar">${btn('edit-decision','Modifier','small',`data-id="${esc(d.id)}"`)}</div></div>`).join(''):empty('Garde ici la trace des choix et de leur raison.')}</section>`;}
  function githubPage(p){
    const cache=githubCache.get(p.id)||{},prep=prepared.get(p.id),remote=remoteDossiers.get(p.id),g=p.github;
    const repoName=g.owner&&g.repo?g.owner+'/'+g.repo:'';
    return heading('CODE & DOCUMENTS','Relier le projet à GitHub.','Choisis le dépôt du projet pour consulter ses fichiers, reprendre des issues et partager le dossier commun.',repoName?link('https://github.com/'+g.owner+'/'+g.repo,'Voir le dépôt'):'')+
    `<div class="grid two"><section class="card"><h2>Le dépôt du projet</h2><form id="repoForm"><label for="repoUrl">Adresse du dépôt ou propriétaire/dépôt</label><input id="repoUrl" name="repo" value="${esc(repoName)}" placeholder="webfourmi/dragon-de-jade" required><div class="field-row"><div><label for="repoBranch">Branche</label><input id="repoBranch" name="branch" value="${esc(g.branch)}" placeholder="Branche par défaut"></div><div><label for="repoPath">Fichier du dossier commun</label><input id="repoPath" name="path" value="${esc(g.path)}" required></div></div><div class="toolbar"><button class="button primary" type="submit">Associer le dépôt</button>${btn('github-test','Vérifier l’accès')}</div></form><div class="connection-status ${cache.repo?'':'disconnected'}">${cache.repo?'Accès vérifié · '+esc(cache.repo.full_name)+' · '+(cache.repo.private?'Dépôt privé':'Dépôt public')+'<br>Branche : '+esc(g.branch||cache.repo.default_branch):repoName?'Dépôt associé. Vérifie l’accès pour lire son contenu.':'Aucun dépôt associé.'}${g.lastSync?'<br>Dernier envoi du dossier : '+esc(formatDate(g.lastSync)):''}</div></section>
    <section class="card"><h2>Accès pour cette session</h2><p class="muted">Les dépôts publics se consultent sans jeton. Un jeton personnel permet d’accéder à tes dépôts privés et d’envoyer le dossier commun.</p><form id="tokenForm"><label for="githubToken">Jeton GitHub</label><input id="githubToken" name="token" type="password" autocomplete="off" spellcheck="false" placeholder="Jeton personnel à accès limité" ${sessionToken?'disabled':''}><div class="toolbar"><button class="button primary" type="submit" ${sessionToken?'disabled':''}>Connecter</button>${sessionToken?btn('github-disconnect','Déconnecter'):''}${btn('github-repos','Choisir parmi les dépôts')}</div></form><p class="help" style="margin-top:16px">${sessionToken?'Connecté en tant que '+esc(sessionUser)+'. Le jeton sera oublié à la fermeture de cette page.':'Le jeton reste en mémoire pour cette page. Il est exclu des sauvegardes et des dossiers exportés.'}</p><details class="disclosure"><summary>Créer un jeton adapté</summary><p>Dans GitHub : Settings → Developer settings → Personal access tokens → Fine-grained tokens. Limite-le aux dépôts souhaités, avec Contents en lecture pour consulter, ou en lecture et écriture pour envoyer le dossier. Ajoute Issues en lecture pour les dépôts privés.</p><a href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">Ouvrir les réglages GitHub ↗</a></details></section></div>
    ${cache.repos?`<section class="card section-gap"><div class="card-heading"><h2>Dépôts disponibles</h2><small class="muted">${cache.repos.length} affichés au maximum sur cette page</small></div><div class="repo-list">${cache.repos.map((r,i)=>`<button class="repo-entry" data-action="pick-repo" data-id="${i}"><span>${esc(r.full_name)}</span><span class="badge">${r.private?'Privé':'Public'}</span></button>`).join('')||empty('Aucun dépôt disponible avec cet accès.')}</div></section>`:''}
    <div class="grid two section-gap"><section class="card"><div class="card-heading"><h2>Fichiers du dépôt</h2>${btn('github-files','Lire les fichiers','small')}</div>${cache.files?`<div class="summary-line">/${esc(cache.path||'')} ${cache.path?btn('github-up','Remonter','small ghost'):''}</div>${cache.files.map((f,i)=>`<div class="repo-file">${f.type==='dir'?`<button data-action="github-open-dir" data-id="${i}">▣ ${esc(f.name)}/</button>`:`<span>${esc(f.name)}</span>${link('https://github.com/'+g.owner+'/'+g.repo+'/blob/'+encodeURIComponent(g.branch||cache.repo?.default_branch||'main')+'/'+f.path.split('/').map(encodeURIComponent).join('/'),'Voir','small ghost')}`}</div>`).join('')||empty('Ce dossier est vide.')}`:'<p class="muted">Consulte la structure du code et ouvre les fichiers dans GitHub.</p>'}</section>
    <section class="card"><div class="card-heading"><h2>Issues ouvertes</h2>${btn('github-issues','Lire les issues','small')}</div><p class="muted">Importe les demandes utiles comme tâches du projet. Leur fermeture dans l’atelier ne ferme pas l’issue sur GitHub.</p>${cache.issues?cache.issues.map((issue,i)=>`<div class="archive-row"><div class="content"><strong>#${issue.number} · ${esc(issue.title)}</strong><small>${esc(issue.state)}</small></div>${btn('import-issue','Ajouter','small',`data-id="${i}"`)}</div>`).join('')||empty('Aucune issue ouverte dans les résultats.'):''}<small class="muted">Lecture des 30 premiers résultats ; les pull requests sont écartées.</small></section></div>
    <section class="card section-gap"><div class="card-heading"><h2>Partager le dossier commun</h2><span class="badge">Un envoi préparé, puis confirmé</span></div><p class="muted">Le fichier partagé contient les objectifs, documents et décisions. Les pièces jointes restent dans le dossier local et le ZIP ; leurs références sont incluses sur GitHub.</p><div class="toolbar">${btn('github-read-dossier','Lire le dossier distant')}${btn('github-prepare','Préparer un envoi','primary')}</div>${prep?`<div class="notice-box section-gap">Destination : <strong>${esc(prep.repo.full_name)}</strong> · <strong>${prep.repo.private?'privée':'publique'}</strong> · branche ${esc(prep.settings.branch)}<br>Fichier : ${esc(prep.settings.path)}<br>${prep.sha?'Le fichier existant sera remplacé.':'Un nouveau fichier sera créé.'}</div><label for="publishPreview">Contenu exact à envoyer</label><textarea id="publishPreview" class="code" readonly>${esc(prep.content)}</textarea><label class="check-label"><input id="publishConsent" type="checkbox">J’ai relu ce dossier et je souhaite l’envoyer dans ce dépôt ${prep.repo.private?'privé':'public'}.</label>${btn('github-publish','Envoyer le dossier sur GitHub','primary',sessionToken?'':'disabled')}<p class="help" style="margin-top:12px">${sessionToken?'Le fichier distant sera vérifié de nouveau pour détecter un conflit.':'Connecte un jeton avec le droit Contents en écriture pour effectuer l’envoi.'}</p>`:''}
    ${remote?`<div class="section-gap"><h3>Dossier actuellement sur GitHub</h3><p class="muted">Projet indiqué : ${esc(remote.payload.project.name)}. Tu peux reprendre ses documents et décisions ; tes tâches et fichiers locaux restent conservés.</p><pre class="code-preview">${esc(JSON.stringify(remote.payload,null,2))}</pre>${btn('github-apply-dossier','Reprendre ces documents et décisions','gold')}</div>`:''}</section>`;
  }
  function promptsPage(){return heading('BIBLIOTHÈQUE COMMUNE','Les consignes réutilisables.','Ces prompts sont disponibles pour tous les projets. Les missions propres aux postes se préparent dans Transmissions IA.',btn('new-prompt','＋ Nouveau prompt','primary'))+`<div class="grid two">${state.prompts.map(p=>`<article class="card"><h3>${esc(p.title)}</h3><label class="muted" for="prompt-${esc(p.id)}">Consigne</label><textarea id="prompt-${esc(p.id)}" data-prompt-id="${esc(p.id)}">${esc(p.text)}</textarea><div class="toolbar">${btn('copy-prompt','Copier','primary',`data-id="${esc(p.id)}"`)}${btn('edit-prompt','Renommer', '',`data-id="${esc(p.id)}"`)}${btn('delete-prompt','Supprimer','ghost danger',`data-id="${esc(p.id)}"`)}</div></article>`).join('')||empty('Ajoute ta première consigne réutilisable.')}</div>`;}
  function comparePage(){
    const d=compareDraft,sc=val=>'<option value="">Non évalué</option>'+[1,2,3,4,5].map(n=>`<option value="${n}" ${String(n)===val?'selected':''}>${n} / 5</option>`).join('');
    return heading('COMPARATEUR DE RÉPONSES','Croiser les regards.','Conserve les réponses, les points à vérifier et ton choix. Le nombre de mots ne mesure pas la justesse.')+
    `<section class="card"><label for="compareTitle">Question ou sujet</label><input id="compareTitle" data-compare-field="title" value="${esc(d.title)}" placeholder="Quel résultat compares-tu ?"><div class="grid two"><div><label for="answerA">Réponse ChatGPT</label><textarea id="answerA" data-compare-field="a" class="comparison-answer">${esc(d.a)}</textarea></div><div><label for="answerB">Réponse Claude</label><textarea id="answerB" data-compare-field="b" class="comparison-answer">${esc(d.b)}</textarea></div></div><div id="compareStats" class="comparison-result">${compareStats()}</div><div class="field-row"><div><label for="compareScoreA">Ton appréciation · ChatGPT</label><select id="compareScoreA" data-compare-field="scoreA">${sc(d.scoreA)}</select></div><div><label for="compareScoreB">Ton appréciation · Claude</label><select id="compareScoreB" data-compare-field="scoreB">${sc(d.scoreB)}</select></div></div><label for="compareNotes">Contradictions, sources et vérifications à faire</label><textarea id="compareNotes" data-compare-field="notes">${esc(d.notes)}</textarea><label for="compareVerdict">Choix retenu et justification</label><textarea id="compareVerdict" data-compare-field="verdict">${esc(d.verdict)}</textarea><div class="toolbar">${btn('save-comparison','Archiver la comparaison','primary')}${btn('copy-comparison','Copier pour analyse croisée')}${btn('reset-comparison','Nouvelle comparaison','ghost')}</div></section><h2 class="section-title">Comparaisons archivées</h2><section class="card">${state.comparisons.map(c=>`<div class="archive-row"><div class="content"><strong>${esc(c.title)}</strong><small>${esc(c.projectName||'Archive V1')} · ${esc(formatDate(c.date))}</small></div>${btn('load-comparison','Recharger','small',`data-id="${esc(c.id)}"`)}</div>`).join('')||empty('Aucune comparaison archivée.')}</section>`;
  }
  function compareStats(){const d=compareDraft,count=s=>s.trim()?s.trim().split(/\s+/).length:0;return !d.a.trim()||!d.b.trim()?'Ajoute les deux réponses pour les comparer.':`ChatGPT : ${count(d.a)} mots · Claude : ${count(d.b)} mots. ${d.a.trim()===d.b.trim()?'Les textes sont identiques.':'Les textes diffèrent ; les affirmations restent à vérifier.'}`;}
  function backupPage(){const history=snapshots();let before=false;try{before=!!localStorage.getItem(BEFORE_KEY);}catch{}return heading('SAUVEGARDES & PROJETS','Garder une trace fiable.','Les textes sont enregistrés automatiquement. Une sauvegarde JSON inclut aussi les pièces jointes disponibles.')+
    `<div class="grid two"><section class="card"><h2>Exporter ou restaurer</h2><p class="muted">Le JSON permet de déplacer tout l’atelier vers un autre navigateur ou ordinateur. Les jetons GitHub en sont exclus.</p><div class="toolbar">${btn('export-all','Exporter tout l’atelier (.json)','primary')}${btn('import-all','Importer une sauvegarde')}${btn('import-project','Ajouter un projet exporté')}</div><p class="help" style="margin-top:15px">L’import complet remplace les données après confirmation. L’ajout d’un projet conserve les autres projets.</p>${before?btn('restore-v1','Restaurer la copie avant migration','small gold'):''}${writeLock==='corrupt'?btn('export-raw','Récupérer les données illisibles','small'):''}</section><section class="card"><h2>Copies automatiques</h2><p class="muted">Jusqu’à cinq états précédents des textes et références sont gardés dans ce navigateur. Pour conserver les fichiers originaux ailleurs, exporte le JSON ou le ZIP.</p>${history.map((s,i)=>`<div class="archive-row"><div class="content"><strong>${esc(formatDate(s.date))}</strong><small>${s.data?.projects?.length||0} projet(s)</small></div>${btn('restore-snapshot','Restaurer','small',`data-id="${i}"`)}</div>`).join('')||empty('Une copie sera créée lors de la prochaine modification.')}</section></div><div class="card-heading section-title"><h2>Tous les projets</h2>${btn('new-project','＋ Nouveau projet','small')}</div><div class="grid three project-grid">${state.projects.map(p=>`<article class="card"><h3>${esc(p.name)}</h3><p class="muted">${esc(p.description)}</p><div class="toolbar">${btn('open-project','Ouvrir','small',`data-id="${esc(p.id)}"`)}${btn('duplicate-project','Dupliquer','small ghost',`data-id="${esc(p.id)}"`)}${btn('delete-project','Supprimer','small ghost danger',`data-id="${esc(p.id)}"`)}</div></article>`).join('')}</div>`;}
  let editorSubmit=null,importMode='replace';
  function editor(title,html,submit,readOnly=false){$('#editorTitle').textContent=title;$('#editorBody').innerHTML=html;$('#editorForm').classList.toggle('dialog-only-action',readOnly);editorSubmit=submit;$('#editor').showModal();}
  function closeEditor(){$('#editor').close();editorSubmit=null;}
  function editProject(p){editor(p?'Modifier le projet':'Nouveau projet',`<label for="editName">Nom du projet</label><input id="editName" name="name" value="${esc(p?.name||'')}" required autofocus><label for="editDesc">Description courte</label><input id="editDesc" name="description" value="${esc(p?.description||'')}"><label for="editVersion">Version actuellement publiée</label><input id="editVersion" name="version" value="${esc(p?.activeVersion||'')}" placeholder="Ex. 0.12.0"><p class="help">La version est un repère de suivi, elle ne déclenche pas de publication.</p>`,fd=>{if(!fd.get('name').trim())throw Error('Donne un nom au projet.');change(()=>{if(p){p.name=fd.get('name').trim();p.description=fd.get('description');p.activeVersion=fd.get('version');}else{const q=C.normalizeProject({id:C.uid(),name:fd.get('name').trim(),description:fd.get('description'),activeVersion:fd.get('version')});state.projects.push(q);projectId=q.id;}});});}
  function editTask(p,t=null,selectedRole='pilotage'){
    const item=t||{id:'',title:'',role:selectedRole,status:'draft',owner:C.role(selectedRole).primaryAI,priority:'normal',objective:'',inputs:'',deliverable:'',criteria:'',evidence:'',blocked:'',dependsOn:[]};
    editor(t?'Ouvrir la tâche':'Confier une nouvelle tâche',`
      <label for="taskTitle">Titre de la tâche</label><input id="taskTitle" name="title" value="${esc(item.title)}" required autofocus>
      <div class="field-row"><div><label for="taskRole">Poste responsable</label><select id="taskRole" name="role">${roleOptions(item.role)}</select></div><div><label for="taskOwner">Intervenant</label><input id="taskOwner" name="owner" list="owners" value="${esc(item.owner)}"><datalist id="owners"><option value="Moi"><option value="ChatGPT"><option value="Claude"></datalist></div></div><p class="help">Intervenant conseillé : ${esc(C.role(item.role).primaryAI)}. Tu peux choisir un autre intervenant.</p>
      <div class="field-row"><div><label for="taskStatus">État</label><select id="taskStatus" name="status">${statusOptions(item.status)}</select></div><div><label for="taskPriority">Priorité</label><select id="taskPriority" name="priority">${[['high','Haute'],['normal','Normale'],['low','Basse']].map(([v,n])=>`<option value="${v}" ${item.priority===v?'selected':''}>${n}</option>`).join('')}</select></div></div>
      <label for="taskObjective">Objectif concret</label><textarea id="taskObjective" name="objective" placeholder="Quel problème cette tâche doit-elle résoudre ?">${esc(item.objective)}</textarea>
      <label for="taskInputs">Éléments à consulter</label><textarea id="taskInputs" name="inputs" placeholder="Documents, fichiers, références et décisions utiles…">${esc(item.inputs)}</textarea>
      <label for="taskDeliverable">Résultat à transmettre au poste suivant</label><textarea id="taskDeliverable" name="deliverable" placeholder="Un texte relu, une illustration, une fonction intégrée…">${esc(item.deliverable)}</textarea>
      <label for="taskCriteria">Comment vérifier que le résultat convient ?</label><textarea id="taskCriteria" name="criteria" placeholder="Des critères observables, des manipulations à tester…">${esc(item.criteria)}</textarea>
      <label for="taskEvidence">Vérifications réalisées et résultat observé</label><textarea id="taskEvidence" name="evidence" placeholder="Indique ce qui a réellement été vérifié, sur quelle version et quel appareil.">${esc(item.evidence)}</textarea>
      <label for="taskBlocked">Blocage éventuel</label><input id="taskBlocked" name="blocked" value="${esc(item.blocked)}" placeholder="Ce qui manque pour avancer">
      <label for="taskDeps">Tâches nécessaires avant celle-ci</label><select id="taskDeps" name="dependsOn" multiple>${p.workItems.filter(x=>x.id!==item.id).map(x=>`<option value="${esc(x.id)}" ${item.dependsOn.includes(x.id)?'selected':''}>${esc(x.title)}</option>`).join('')}</select><p class="help">Sélection multiple avec Ctrl ou ⌘. Une tâche bloquée ne peut pas être marquée terminée.</p>
      ${t?.source?.url&&externalHref(t.source.url)?link(externalHref(t.source.url),'Ouvrir l’issue GitHub','small'):''}
      ${t?'<div class="toolbar">'+btn('task-to-transfer','Préparer une transmission','small',`data-id="${esc(t.id)}"`)+btn('delete-task','Supprimer la tâche','small ghost danger',`data-id="${esc(t.id)}"`)+'</div>':''}`,fd=>{
      const next={...item,title:fd.get('title').trim(),role:fd.get('role'),owner:fd.get('owner').trim()||'Moi',status:fd.get('status'),priority:fd.get('priority'),objective:fd.get('objective'),inputs:fd.get('inputs'),deliverable:fd.get('deliverable'),criteria:fd.get('criteria'),evidence:fd.get('evidence'),blocked:fd.get('blocked'),dependsOn:fd.getAll('dependsOn'),updatedAt:now(),id:item.id||C.uid()};
      if(!next.title)throw Error('Donne un titre à la tâche.');
      const reach=(id,seen=new Set())=>{if(id===next.id)return true;if(seen.has(id))return false;seen.add(id);return (p.workItems.find(x=>x.id===id)?.dependsOn||[]).some(d=>reach(d,seen));};
      if(next.dependsOn.some(id=>reach(id)))throw Error('Ces dépendances forment une boucle. Choisis une autre organisation.');
      if(next.status==='done'&&(next.blocked||C.unresolved(p,next).length))throw Error('Lève le blocage et termine les tâches nécessaires avant de clôturer celle-ci.');
      change(()=>{if(t)Object.assign(t,next);else p.workItems.push(next);});
    });
  }
  function editDocument(p,d){editor(d?'Document de référence':'Ajouter un document',`<label for="documentTitle">Titre</label><input id="documentTitle" name="title" value="${esc(d?.title||'')}" required><label for="documentContent">Contenu de référence</label><textarea id="documentContent" name="content" class="tall">${esc(d?.content||'')}</textarea>`,fd=>{if(!fd.get('title').trim())throw Error('Donne un titre au document.');change(()=>{if(d){d.title=fd.get('title').trim();d.content=fd.get('content');d.updatedAt=now();}else p.documents.push({id:C.uid(),title:fd.get('title').trim(),kind:'note',content:fd.get('content'),updatedAt:now()});});});}
  function editDecision(p,d){editor(d?'Modifier la décision':'Consigner une décision',`<label for="decisionText">Décision ou proposition</label><textarea id="decisionText" name="text" required autofocus>${esc(d?.text||'')}</textarea><label for="decisionReason">Pourquoi ce choix ?</label><textarea id="decisionReason" name="reason">${esc(d?.reason||'')}</textarea><label for="decisionStatus">État de la décision</label><select id="decisionStatus" name="status">${[['proposed','Proposée · à examiner'],['validated','Validée · fait référence'],['retired','Remplacée / retirée']].map(([v,n])=>`<option value="${v}" ${d?.status===v?'selected':''}>${n}</option>`).join('')}</select>`,fd=>{if(!fd.get('text').trim())throw Error('Renseigne la décision.');change(()=>{const value={text:fd.get('text').trim(),reason:fd.get('reason'),status:fd.get('status'),date:now()};if(d)Object.assign(d,value);else p.decisionLog.unshift({id:C.uid(),...value});});});}
  function editAsset(p,a){editor('Suivi du fichier',`<p><strong>${esc(a.name)}</strong></p><div class="field-row"><div><label for="assetStatus">Avancement du média</label><select id="assetStatus" name="status">${C.ASSET_STATUSES.map(s=>`<option value="${s.id}" ${a.status===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div><div><label for="assetRole">Poste concerné</label><select id="assetRole" name="role">${roleOptions(a.role)}</select></div></div><label for="assetNote">Usage, emplacement et vérifications</label><textarea id="assetNote" name="note">${esc(a.note)}</textarea>${btn('remove-asset','Retirer du dossier','small danger',`data-id="${esc(a.id)}"`)}`,fd=>change(()=>{a.status=fd.get('status');a.role=fd.get('role');a.note=fd.get('note');}));}
  function openDB(){
    if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('Les fichiers ne peuvent pas être conservés dans ce navigateur.'));const req=indexedDB.open('atelier-ia-files-v2',1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('Le stockage des fichiers est indisponible.'));req.onblocked=()=>reject(Error('Ferme les autres fenêtres de l’atelier pour ouvrir le stockage des fichiers.'));});
    return dbPromise;
  }
  async function putFiles(records){if(!records.length)return;const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');for(const r of records)tx.objectStore('files').put(r);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('L’enregistrement des fichiers a échoué. Vérifie l’espace disponible.'));tx.onabort=()=>reject(Error('Le stockage des fichiers est saturé ou bloqué.'));});}
  async function getFile(id){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readonly'),req=tx.objectStore('files').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('Impossible de relire ce fichier.'));});}
  function download(name,blob,type){const data=blob instanceof Blob?blob:new Blob([blob],{type:type||'text/plain;charset=utf-8'}),url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  async function copy(text){try{await navigator.clipboard.writeText(text);toast('Texte copié.');}catch{editor('Copier le texte',`<p class="muted">Sélectionne le texte ci-dessous, puis utilise Ctrl+C ou ⌘C.</p><label for="copyFallback">Texte à copier</label><textarea id="copyFallback" class="code" readonly>${esc(text)}</textarea>`,null,true);$('#copyFallback').select();}}
  async function blobBase64(blob){const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary);}
  async function backupData(projects=null){
    const data=C.clone(projects?{schemaVersion:2,projects,prompts:[],comparisons:[]}:state),attachments=[],missing=[],seen=new Set();
    for(const p of data.projects)for(const a of p.assets){if(seen.has(a.id))continue;seen.add(a.id);let file;try{file=await getFile(a.id);}catch{}if(file?.blob)attachments.push({id:a.id,name:a.name,type:a.type,base64:await blobBase64(file.blob)});else missing.push(a.name);}
    return {format:projects?'atelier-project':'atelier-backup',version:2,appVersion:C.VERSION,exportedAt:now(),data,attachments,missingFiles:missing};
  }
  async function exportAll(){const envelope=await backupData();download('mon-atelier-ia-sauvegarde-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(envelope,null,2),'application/json');toast(envelope.missingFiles.length?'Sauvegarde exportée ; '+envelope.missingFiles.length+' fichier(s) absent(s), listé(s) dans missingFiles.':'Sauvegarde complète exportée.');}
  async function projectFiles(p){
    const envelope=await backupData([p]),files=[{name:'DOSSIER_COMMUN.md',blob:new Blob([C.markdown(p)],{type:'text/markdown;charset=utf-8'})},{name:'projet.json',blob:new Blob([JSON.stringify(envelope,null,2)],{type:'application/json'})}];
    for(const a of p.assets){let f;try{f=await getFile(a.id);}catch{}if(f?.blob)files.push({name:'pieces-jointes/'+C.slug(a.id)+'-'+C.safeFilename(a.name),blob:f.blob});}
    if(envelope.missingFiles.length)files.push({name:'FICHIERS_MANQUANTS.txt',blob:new Blob(['Ces fichiers ne sont pas disponibles dans ce navigateur :\n'+envelope.missingFiles.join('\n')])});
    return {files,missing:envelope.missingFiles};
  }
  async function exportProject(p){const {files,missing}=await projectFiles(C.clone(p));download(C.slug(p.name)+'-dossier-commun.zip',await C.makeZip(files));toast(missing.length?'Dossier exporté avec la liste des fichiers manquants.':'Dossier exporté avec les fichiers originaux.');}
  async function writeFolder(){
    if(!folderHandle)throw Error('Choisis d’abord un dossier local.');if(folderWriting){folderAgain=true;return;}folderWriting=true;
    try{if(folderHandle.queryPermission&&await folderHandle.queryPermission({mode:'readwrite'})!=='granted')throw Error('L’accès au dossier local a expiré. Sélectionne-le à nouveau.');const p=C.clone(current());if(!p)return;const {files,missing}=await projectFiles(p),root=await folderHandle.getDirectoryHandle('mon-atelier-ia',{create:true}),target=await root.getDirectoryHandle(C.slug(p.name)+'-'+C.slug(p.id).slice(0,12),{create:true});
      for(const f of files){let parent=target;const parts=f.name.split('/');for(const dir of parts.slice(0,-1))parent=await parent.getDirectoryHandle(dir,{create:true});const handle=await parent.getFileHandle(parts.at(-1),{create:true}),stream=await handle.createWritable();await stream.write(f.blob);await stream.close();}
      toast(missing.length?'Dossier local enregistré avec une liste des fichiers manquants.':'Projet et fichiers enregistrés dans le dossier local.');
    }finally{folderWriting=false;if(folderAgain){folderAgain=false;clearTimeout(folderTimer);folderTimer=setTimeout(()=>writeFolder().catch(e=>toast(e.message)),1000);}}
  }
  async function chooseFolder(){if(!window.showDirectoryPicker)throw Error('Ce navigateur ne permet pas de choisir un dossier en écriture. Utilise l’export ZIP, ou ouvre l’atelier dans Chrome / Edge sur ordinateur.');folderHandle=await window.showDirectoryPicker({id:'atelier-ia-common',mode:'readwrite'});await writeFolder();render();}
  async function importBackup(file,mode){
    const envelope=JSON.parse(await file.text()),next=C.normalizeState(envelope.data||envelope),records=[],mapping=new Map();
    if(envelope.attachments!==undefined&&!Array.isArray(envelope.attachments))throw Error('La liste des pièces jointes est invalide.');
    for(const a of envelope.attachments||[]){if(!a||typeof a.id!=='string'||typeof a.base64!=='string'||!/^[A-Za-z0-9+/]*={0,2}$/.test(a.base64))throw Error('Une pièce jointe est invalide.');if(mapping.has(a.id))throw Error('Une pièce jointe est déclarée deux fois.');const binary=atob(a.base64),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)),id=C.uid();mapping.set(a.id,id);records.push({id,blob:new Blob([bytes],{type:C.text(a.type)||'application/octet-stream'})});}
    const referenced=new Set(next.projects.flatMap(p=>p.assets.map(a=>a.id)));if(records.length&&[...mapping.keys()].some(id=>!referenced.has(id)))throw Error('Une pièce jointe ne correspond à aucun fichier du projet.');
    for(const p of next.projects){if(mode==='merge'&&state.projects.some(x=>x.id===p.id)){p.id=C.uid();p.name+=' (importé)';}for(const a of p.assets){const old=a.id;a.id=mapping.get(old)||C.uid();const stored=records.find(r=>r.id===a.id);if(stored)a.size=stored.blob.size;}}
    const message=mode==='merge'?'Ajouter '+next.projects.length+' projet(s) sans remplacer les projets actuels ?':'Remplacer l’atelier actuel par cette sauvegarde ? Une copie des textes actuels sera conservée.';
    if(!confirm(message))return;
    await putFiles(records);snapshot(true);
    if(mode==='merge'){if(!editable())return;state.projects.push(...next.projects);}else{state=next;writeLock='';}
    projectId=next.projects[0]?.id||state.projects[0]?.id||'';if(mode!=='merge')lastRaw=localStorage.getItem(C.KEY);persist();navigate('pilotage');render();const missing=next.projects.flatMap(p=>p.assets).filter(a=>!records.some(r=>r.id===a.id)).length;toast(missing?'Import effectué ; '+missing+' original(aux) à ajouter à nouveau.':'Import effectué, avec les fichiers disponibles dans la sauvegarde.');
  }
  function githubSettings(p){if(!p.github.owner||!p.github.repo)throw Error('Associe d’abord un dépôt au projet.');return {...p.github,path:C.safePath(p.github.path)};}
  function githubIdentity(p){return JSON.stringify([p.github.owner,p.github.repo,p.github.branch,p.github.path]);}
  function checkGithubIdentity(p,identity){if(!state.projects.includes(p)||githubIdentity(p)!==identity)throw Error('Le dépôt associé a changé pendant la lecture. Relance l’action avec le nouveau dépôt.');}
  function cacheFor(p){if(!githubCache.has(p.id))githubCache.set(p.id,{});return githubCache.get(p.id);}
  async function checkGithub(p){const identity=githubIdentity(p),g=githubSettings(p),meta=await gh.repo(g);checkGithubIdentity(p,identity);if(!editable())return;change(()=>{if(!p.github.branch)p.github.branch=meta.default_branch;},false);const c=cacheFor(p);c.repo=meta;render();toast('Accès GitHub vérifié.');return meta;}
  async function githubFiles(p,path=''){let identity=githubIdentity(p),g=githubSettings(p);if(!g.branch){const meta=await gh.repo(g);checkGithubIdentity(p,identity);g.branch=meta.default_branch;change(()=>p.github.branch=g.branch,false);identity=githubIdentity(p);cacheFor(p).repo=meta;}const entries=await gh.contents(g,path);checkGithubIdentity(p,identity);if(!Array.isArray(entries))throw Error('Ce dossier est introuvable ou le dépôt est vide.');const cache=cacheFor(p);cache.files=entries;cache.path=path;render();}
  async function githubRepos(p){const identity=githubIdentity(p),owner=p.github.owner||'webfourmi',repos=await gh.repositories(owner);checkGithubIdentity(p,identity);cacheFor(p).repos=Array.isArray(repos)?repos:[];render();}
  async function prepareGithub(p){const identity=githubIdentity(p),content=JSON.stringify(C.sharedPayload(p),null,2);if(new Blob([content]).size>850000)throw Error('Le dossier dépasse 850 Ko. Exporte le ZIP pour transmettre ce projet.');const preview=await gh.prepare(githubSettings(p),content);checkGithubIdentity(p,identity);prepared.set(p.id,preview);render();toast('Aperçu prêt. Vérifie le contenu et la destination.');}
  async function publishGithub(p){
    if(!editable())return;
    const preview=prepared.get(p.id);if(!preview)throw Error('Prépare d’abord un aperçu.');if(!$('#publishConsent')?.checked)throw Error('Confirme l’envoi après avoir relu l’aperçu.');
    const g=githubSettings(p),sameSettings=['owner','repo','path'].every(k=>g[k]===preview.settings[k])&&(!g.branch||g.branch===preview.settings.branch);
    if(!sameSettings||JSON.stringify(C.sharedPayload(p),null,2)!==preview.content)throw Error('Le projet a changé depuis l’aperçu. Prépare un nouvel envoi.');
    const identity=githubIdentity(p),result=await gh.publish(preview);if(state.projects.includes(p)&&githubIdentity(p)===identity)change(()=>{p.github.lastSync=now();p.github.lastSha=result.content?.sha||'';p.github.branch=preview.settings.branch;},false);prepared.delete(p.id);remoteDossiers.delete(p.id);render();toast('Dossier commun enregistré sur GitHub : '+preview.settings.owner+'/'+preview.settings.repo+'.');
  }
  async function readGithubDossier(p){const identity=githubIdentity(p),g=githubSettings(p);if(!g.branch){const m=await gh.repo(g);checkGithubIdentity(p,identity);g.branch=m.default_branch;}const file=await gh.contents(g,g.path);checkGithubIdentity(p,identity);if(!file)throw Error('Il n’y a pas encore de dossier commun à ce chemin.');if(!file.content||file.encoding!=='base64')throw Error('Ce fichier est trop volumineux ou n’est pas lisible comme dossier commun.');const payload=JSON.parse(C.fromBase64(file.content));C.applyShared(p,payload);remoteDossiers.set(p.id,{payload,sha:file.sha,settings:g});render();toast('Dossier distant chargé pour consultation.');}
  function updateTransfer(){const p=current();if(!p)return;const value=C.context(p,transferDraft.level,transferDraft.role,transferDraft.task,transferDraft.request);if($('#transferOutput'))$('#transferOutput').value=value;if($('#transferLength'))$('#transferLength').textContent=value.length.toLocaleString('fr-FR')+' caractères';const a=$('#openAI');if(a){a.href=transferDraft.to==='Claude'?'https://claude.ai':'https://chatgpt.com';a.textContent='Ouvrir '+(transferDraft.to==='Moi'?'ChatGPT':transferDraft.to)+' ↗';}change(()=>p.transferDraft={...transferDraft},false);}
  function loadProjectDraft(){const p=current();draftProjectId=p?.id||'';transferDraft={from:'Moi',to:'ChatGPT',level:'standard',role:'pilotage',task:'',request:'',...p?.transferDraft};if(!['court','standard','complet'].includes(transferDraft.level))transferDraft.level='standard';transferDraft.role=C.role(transferDraft.role).id;}
  async function action(name,el){
    const p=current(),id=el.dataset.id;
    switch(name){
      case 'new-project':if(editable())editProject(null);break;
      case 'edit-project':if(editable())editProject(p);break;
      case 'open-project':setProject(id);loadProjectDraft();navigate('pilotage');break;
      case 'duplicate-project':if(editable()){const original=state.projects.find(x=>x.id===id);change(()=>{const q=C.clone(original);q.id=C.uid();q.name+=' (copie)';q.github.path='.atelier-ia/'+C.slug(q.id)+'/dossier-commun.json';delete q.github.lastSync;delete q.github.lastSha;state.projects.push(q);projectId=q.id;});loadProjectDraft();toast('Projet dupliqué.');}break;
      case 'delete-project':{const target=state.projects.find(x=>x.id===id);if(target&&editable()&&confirm('Supprimer le projet « '+target.name+' » ? Une copie des textes sera conservée.')){snapshot(true);change(()=>{state.projects=state.projects.filter(x=>x.id!==id);projectId=state.projects[0]?.id||'';});loadProjectDraft();}break;}
      case 'new-task':if(editable())editTask(p,null,el.dataset.role||roleId||filterRole||'pilotage');break;
      case 'edit-task':if(editable())editTask(p,p.workItems.find(t=>t.id===id));break;
      case 'delete-task':{const t=p.workItems.find(x=>x.id===id);if(t&&confirm('Supprimer cette tâche ? Les tâches qui en dépendent seront signalées comme bloquées.')){change(()=>{p.workItems=p.workItems.filter(x=>x.id!==id);for(const x of p.workItems)if(x.dependsOn.includes(id)){x.dependsOn=x.dependsOn.filter(d=>d!==id);x.blocked=x.blocked||'Prérequis supprimé : '+t.title+'. Revoir cette dépendance.';if(x.status==='done')x.status='review';}});closeEditor();}break;}
      case 'task-to-transfer':{if(!$('#editorForm').reportValidity())return;if(editorSubmit)await editorSubmit(new FormData($('#editorForm')));closeEditor();const t=p.workItems.find(x=>x.id===id);transferDraft.task=id;transferDraft.role=t.role;selectRoleAI(t.role);transferDraft.request='';change(()=>p.transferDraft={...transferDraft},false);navigate('transmissions');break;}
      case 'role-handoff':transferRoleAction(el.dataset.role);break;
      case 'role-review':transferRoleAction(el.dataset.role,true);break;
      case 'dossier-tab':docTab=id;render();break;
      case 'new-document':if(editable())editDocument(p,null);break;
      case 'edit-document':if(editable())editDocument(p,p.documents.find(d=>d.id===id));break;
      case 'copy-document':await copy(p.documents.find(d=>d.id===id).content);break;
      case 'copy-dossier':await copy(C.markdown(p));break;
      case 'new-decision':if(editable())editDecision(p,null);break;
      case 'edit-decision':if(editable())editDecision(p,p.decisionLog.find(d=>d.id===id));break;
      case 'add-assets':if(editable()){assetProjectId=p.id;$('#assetFiles').click();}break;
      case 'edit-asset':if(editable())editAsset(p,p.assets.find(a=>a.id===id));break;
      case 'remove-asset':if(confirm('Retirer ce fichier du dossier courant ? Les anciennes copies automatiques gardent sa référence.')){change(()=>p.assets=p.assets.filter(a=>a.id!==id));closeEditor();}break;
      case 'download-asset':{const a=p.assets.find(a=>a.id===id),f=await getFile(id);if(!f?.blob)throw Error('L’original de ce fichier est absent. Importe la sauvegarde complète ou ajoute-le à nouveau.');download(a.name,f.blob);break;}
      case 'copy-transfer':await copy($('#transferOutput').value);break;
      case 'archive-transfer':change(()=>{const t=p.workItems.find(t=>t.id===transferDraft.task);p.handoffs.unshift({id:C.uid(),title:t?.title||C.role(transferDraft.role).name,from:transferDraft.from,to:transferDraft.to,date:now(),role:transferDraft.role,taskId:transferDraft.task,result:'',notes:'',rating:0,outcome:'pending',content:C.context(p,transferDraft.level,transferDraft.role,transferDraft.task,transferDraft.request)});});toast('Transmission préparée et archivée.');break;
      case 'edit-mission':if(editable())editMission(p,p.handoffs.find(h=>h.id===id));break;
      case 'open-transfer':{const h=p.handoffs.find(x=>x.id===id);editor('Transmission archivée',`<p class="muted">${esc(h.from)} → ${esc(h.to)} · ${esc(formatDate(h.date))}</p><label for="archivedTransfer">Consigne conservée</label><textarea id="archivedTransfer" class="code" readonly>${esc(h.content)}</textarea>${btn('copy-archived-transfer','Copier cette transmission','primary',`data-id="${esc(id)}"`)}`,null,true);break;}
      case 'copy-archived-transfer':await copy(p.handoffs.find(x=>x.id===id).content);break;
      case 'new-prompt':if(editable())editor('Nouvelle consigne',`<label for="promptTitle">Titre</label><input id="promptTitle" name="title" required><label for="promptText">Consigne</label><textarea id="promptText" name="text" required></textarea>`,fd=>change(()=>state.prompts.push({id:C.uid(),title:fd.get('title').trim(),text:fd.get('text')})));break;
      case 'edit-prompt':{const prompt=state.prompts.find(x=>x.id===id);if(editable())editor('Renommer la consigne',`<label for="promptTitle">Titre</label><input id="promptTitle" name="title" value="${esc(prompt.title)}" required>`,fd=>change(()=>prompt.title=fd.get('title').trim()));break;}
      case 'copy-prompt':await copy(state.prompts.find(x=>x.id===id).text);break;
      case 'delete-prompt':if(confirm('Supprimer cette consigne ?'))change(()=>state.prompts=state.prompts.filter(x=>x.id!==id));break;
      case 'save-comparison':if(!compareDraft.a.trim()||!compareDraft.b.trim())throw Error('Ajoute les deux réponses avant d’archiver.');change(()=>{const value={...compareDraft,id:compareDraft.id||C.uid(),title:compareDraft.title.trim()||'Sans titre',date:now(),projectId:p?.id||'',projectName:p?.name||''};const old=state.comparisons.findIndex(x=>x.id===value.id);if(old>=0)state.comparisons[old]=value;else state.comparisons.unshift(value);compareDraft={...value};state.drafts={...state.drafts,comparison:compareDraft};});toast('Comparaison archivée.');break;
      case 'load-comparison':compareDraft={title:'',a:'',b:'',notes:'',verdict:'',scoreA:'',scoreB:'',...state.comparisons.find(x=>x.id===id)};change(()=>state.drafts={...state.drafts,comparison:compareDraft});break;
      case 'reset-comparison':compareDraft={title:'',a:'',b:'',notes:'',verdict:'',scoreA:'',scoreB:''};change(()=>state.drafts={...state.drafts,comparison:compareDraft});break;
      case 'copy-comparison':await copy(`Analyse ces réponses sur le fond. Vérifie les affirmations à partir de sources et relève les contradictions, omissions et éléments non vérifiés.\n\nQuestion : ${compareDraft.title}\n\nCHATGPT\n${compareDraft.a}\n\nCLAUDE\n${compareDraft.b}\n\nNotes de vérification\n${compareDraft.notes}`);break;
      case 'choose-folder':await chooseFolder();break;
      case 'write-folder':await writeFolder();break;
      case 'export-project':await exportProject(p);break;
      case 'export-all':await exportAll();break;
      case 'import-all':importMode='replace';$('#importFile').click();break;
      case 'import-project':importMode='merge';$('#importFile').click();break;
      case 'restore-snapshot':{const backup=snapshots()[Number(id)];if(backup&&confirm('Restaurer cet état de l’atelier ? L’état actuel sera aussi conservé.')){const next=C.normalizeState(backup.data);snapshot(true);state=next;writeLock='';lastRaw=localStorage.getItem(C.KEY);projectId=state.projects[0]?.id||'';persist();loadProjectDraft();render();toast('Copie restaurée.');}break;}
      case 'restore-v1':if(confirm('Restaurer la copie de la V1 conservée avant migration ?')){const raw=localStorage.getItem(BEFORE_KEY),next=C.normalizeState(JSON.parse(raw));snapshot(true);state=next;writeLock='';lastRaw=localStorage.getItem(C.KEY);projectId=state.projects[0]?.id||'';persist();loadProjectDraft();render();toast('Copie de la V1 restaurée.');}break;
      case 'export-raw':download('mon-atelier-ia-donnees-originales.txt',localStorage.getItem(C.KEY)||lastRaw||'','text/plain');break;
      case 'reload':location.reload();break;
      case 'github-test':await checkGithub(p);break;
      case 'github-repos':await githubRepos(p);break;
      case 'pick-repo':{const r=cacheFor(p).repos[Number(id)];if(!r)return;change(()=>{p.github={owner:r.owner.login,repo:r.name,branch:r.default_branch,path:p.github.path||'.atelier-ia/dossier-commun.json'};},false);const repos=cacheFor(p).repos;githubCache.set(p.id,{repo:r,repos});prepared.delete(p.id);remoteDossiers.delete(p.id);render();toast('Dépôt associé au projet.');break;}
      case 'github-files':await githubFiles(p);break;
      case 'github-up':await githubFiles(p,(cacheFor(p).path||'').split('/').slice(0,-1).join('/'));break;
      case 'github-open-dir':await githubFiles(p,cacheFor(p).files[Number(id)].path);break;
      case 'github-issues':{const identity=githubIdentity(p),issues=await gh.issues(githubSettings(p));checkGithubIdentity(p,identity);cacheFor(p).issues=issues.filter(x=>!x.pull_request);render();break;}
      case 'import-issue':{const issue=cacheFor(p).issues[Number(id)],repo=p.github.owner+'/'+p.github.repo;if(p.workItems.some(t=>t.source?.repo===repo&&t.source?.number===issue.number))throw Error('Cette issue a déjà été ajoutée aux tâches.');change(()=>p.workItems.push({id:C.uid(),title:issue.title,role:'programmation',status:'ready',owner:'Moi',priority:'normal',objective:C.text(issue.body),inputs:'Issue GitHub : '+issue.html_url,deliverable:'',criteria:'',evidence:'',blocked:'',dependsOn:[],updatedAt:now(),source:{repo,number:issue.number,url:issue.html_url}}));toast('Issue ajoutée aux tâches.');break;}
      case 'github-disconnect':sessionToken='';sessionUser='';githubCache.clear();prepared.clear();remoteDossiers.clear();render();toast('Jeton oublié.');break;
      case 'github-prepare':await prepareGithub(p);break;
      case 'github-publish':await publishGithub(p);break;
      case 'github-read-dossier':await readGithubDossier(p);break;
      case 'github-apply-dossier':{const r=remoteDossiers.get(p.id);if(!r)return;if(!['owner','repo','path'].every(k=>p.github[k]===r.settings[k]))throw Error('Le dépôt associé a changé. Relis le dossier distant.');if(confirm('Reprendre les documents et décisions du dossier « '+C.text(r.payload.project.name)+' » ? Une copie des textes actuels sera conservée.')){snapshot(true);change(()=>Object.assign(p,C.applyShared(p,r.payload)));remoteDossiers.delete(p.id);render();toast('Documents et décisions repris.');}break;}
      case 'close-dialog':closeEditor();break;
    }
  }
  let assetProjectId='';
  document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(el.disabled)return;const original=el.disabled;el.disabled=true;try{await action(el.dataset.action,el);}catch(e){if(e.name!=='AbortError')toast(e.message||'Cette action a échoué.');}finally{el.disabled=original;}});
  document.addEventListener('submit',async event=>{
    if(event.target.id==='editorForm'){event.preventDefault();if(!editorSubmit)return;const submit=event.target.querySelector('button[type=submit]');submit.disabled=true;try{await editorSubmit(new FormData(event.target));closeEditor();}catch(e){toast(e.message);}finally{submit.disabled=false;}}
    if(event.target.id==='repoForm'){event.preventDefault();try{const fd=new FormData(event.target),repo=C.parseRepo(fd.get('repo')),path=C.safePath(fd.get('path')),branch=fd.get('branch').trim();if(/[\x00-\x1f]/.test(branch))throw Error('Le nom de branche est invalide.');const p=current();change(()=>{p.github={...repo,branch,path};githubCache.delete(p.id);prepared.delete(p.id);remoteDossiers.delete(p.id);});toast('Dépôt associé. Tu peux vérifier son accès.');}catch(e){toast(e.message);}}
    if(event.target.id==='tokenForm'){event.preventDefault();const input=$('#githubToken'),token=input.value.trim();if(!token){toast('Ajoute un jeton pour ouvrir une session GitHub.');return;}input.value='';const button=event.target.querySelector('button[type=submit]');button.disabled=true;sessionToken=token;try{const user=await gh.request('/user');sessionUser=user.login;render();toast('Session GitHub ouverte.');}catch(e){sessionToken='';sessionUser='';button.disabled=false;toast(e.message);}}
  });
  document.addEventListener('input',event=>{
    const el=event.target,p=current();
    if(el.dataset.projectField)change(()=>p[el.dataset.projectField]=el.value,false);
    if(el.dataset.promptId){const item=state.prompts.find(x=>x.id===el.dataset.promptId);if(item)change(()=>item.text=el.value,false);}
    if(el.dataset.transferField){transferDraft[el.dataset.transferField]=el.value;if(el.dataset.transferField==='task'){const t=p.workItems.find(t=>t.id===el.value);if(t){transferDraft.role=t.role;$('#transferRole').value=t.role;selectRoleAI(t.role);$('#transferTo').value=transferDraft.to;}}if(el.dataset.transferField==='role'){selectRoleAI(el.value);$('#transferTo').value=transferDraft.to;const advice=$('#aiRecommendation');if(advice)advice.textContent='Conseil pour ce poste : '+C.role(el.value).primaryAI+' en principal · '+C.role(el.value).reviewAI+' en contrôle. Le choix « Vers » reste libre.';}updateTransfer();}
    if(el.dataset.compareField){compareDraft[el.dataset.compareField]=el.value;change(()=>state.drafts={...state.drafts,comparison:{...compareDraft}},false);if($('#compareStats'))$('#compareStats').textContent=compareStats();}
    if(el.id==='taskSearch'){const position=el.selectionStart;filterQuery=el.value;render();const input=$('#taskSearch');input.focus();input.setSelectionRange(position,position);}
  });
  document.addEventListener('change',event=>{const el=event.target;if(el.id==='projectSelect'){setProject(el.value);loadProjectDraft();render();}if(el.id==='filterRole'){filterRole=el.value;render();}if(el.id==='taskRole'&&!$('#editor').classList.contains('dialog-only-action')){const owner=$('#taskOwner');if(owner&&['Moi','ChatGPT','Claude'].includes(owner.value))owner.value=C.role(el.value).primaryAI;}if(el.id==='filterOwner'){filterOwner=el.value;render();}if(el.id==='folderAuto'){folderAuto=el.checked;if(folderAuto)writeFolder().catch(e=>{folderAuto=false;toast(e.message);render();});}});
  $('#importFile').addEventListener('change',async event=>{const file=event.target.files[0];try{if(file)await importBackup(file,importMode);loadProjectDraft();}catch(e){toast('Import impossible : '+e.message);}finally{event.target.value='';}});
  $('#assetFiles').addEventListener('change',async event=>{
    const files=[...event.target.files],p=state.projects.find(p=>p.id===assetProjectId);try{if(!p||!files.length||!editable())return;for(const f of files)if(f.size>50*1024*1024)throw Error('Le fichier « '+f.name+' » dépasse 50 Mo. Ajoute plutôt un lien dans les références.');const records=files.map(file=>({id:C.uid(),blob:file}));await putFiles(records);change(()=>records.forEach((r,i)=>p.assets.push({id:r.id,name:files[i].name,size:files[i].size,type:files[i].type,role:'medias',status:'available',note:'',date:now()})));toast(files.length+' fichier(s) ajouté(s), dans leur définition originale.');}catch(e){toast(e.message);}finally{event.target.value='';}
  });
  window.addEventListener('storage',event=>{if(event.key===C.KEY&&event.newValue!==lastRaw){writeLock='conflict';announce();$('#saveStatus').textContent='Une autre fenêtre a modifié l’atelier';}});
  window.addEventListener('hashchange',route);
  load();loadProjectDraft();compareDraft={...compareDraft,...state.drafts?.comparison};if(!writeLock&&!storageError)persist();route();
})();
